// OneBodyOperatorJT: expand a one-body operator into U(3)xU(4) tensors and
// write the expansion file that SAM reads in later calculations.
//
// Most users never need this: the expansions of the common operators are
// released (make data, make data-list). Run it for an operator that is not
// released, or to reach a larger maxShell than the released file.
//
// Do not edit this file; copy it into app/work/ and edit the copy:
//   cp app/tutorial/OneBodyOperatorJT.cpp app/work/
//   make -j 8 apps && mpirun -np 1 bin/work/OneBodyOperatorJT
//
// The file is written to
//   <data dir>/OneBodyOperatorJT/<name>/Expansion/<name>_hw<hw>
// and serves every calculation whose maxShell (valence shell + Nmax) is not
// larger than the maxShell below. One-body expansions are cheap (seconds),
// so an existing file is simply replaced; a released file is read-only and
// must be unlocked first (chmod u+w <file>).

#include <chrono>
#include <iostream>
#include <set>
#include <string>

#include <print.h>

#include <sam.h>
#include <ExpansionFiles.h>
#include <OneBodyOperatorJT.h>

int main(int argc, char* argv[])
{
  using utils::print;

  sam::initialize(&argc, &argv);

  ////////////// SETTINGS //////////////

  // the operator; SAM computes these itself:
  //   "NumberOp"           total number of HO quanta
  //   "L.L", "L.S"         one-body parts of L.L and L.S
  //   "Kinetic"            one-body part of the relative kinetic energy
  //   "CoMNumberOp"        one-body part of the CoM HO number operator
  //   "Rrel"               one-body part of the intrinsic radius squared
  //   "Radius", "Radius_p", "Radius_n"   point-nucleon, -proton, -neutron
  //                        radius squared, summed over nucleons
  //   "E2", "M1"           electric quadrupole, magnetic dipole
  //   "FermiMinus", "FermiPlus", "GamowTellerMinus", "GamowTellerPlus"
  // any other name is read from a one-body interaction file in the data
  // directory.
  std::string name = "E2";

  // largest HO shell (N = 0, 1, 2, ...) the expansion reaches; a nucleus
  // with valence shell v at Nmax needs maxShell >= v + Nmax:
  int maxShell = 8;

  // HO energy (MeV). Keep hw = 20 for the operators SAM computes itself:
  // their expansion is stored once at 20 MeV and rescaled to any hw when
  // read. An interaction file has its own hw.
  int hw = 20;

  bool print_tensors = false;   // list every tensor and its strengths

  ////////////// DON'T EDIT ANYTHING BELOW //////////////

#ifdef USE_MPI
  int mpi_rank = 0;
  MPI_Comm_rank(MPI_COMM_WORLD, &mpi_rank);
  const bool root = (mpi_rank == 0);
#else
  const bool root = true;
#endif

  const std::set<std::string> computed_by_sam = {
      "NumberOp", "L.L", "L.S", "CoMNumberOp", "Kinetic", "Rrel", "Radius",
      "Radius_p", "Radius_n", "E2", "M1", "FermiMinus", "FermiPlus",
      "GamowTellerMinus", "GamowTellerPlus"};
  if (computed_by_sam.count(name) && hw != 20)
    throw std::invalid_argument(
        "Sorry, " + name + " is expanded at hw = 20 MeV only (SAM rescales "
        "it to other hw when reading); set hw = 20");

  HO::Table_nljmjmt HO_labels(maxShell);
  U3xU4::Table_gelfand gelfand_labels(maxShell);

  // a reusable expansion has no valence shell and Nmax = maxShell:
  JT::OneBodyOperator op(name, hw, maxShell, 0, maxShell, HO_labels,
                         gelfand_labels);
  if (root) op.is();

  std::string filename = op.dirname() + "/Expansion/" + name + "_hw" +
                         std::to_string(hw);
  sam::require_writable(filename);   // stop now if it cannot be written

  auto t0 = std::chrono::steady_clock::now();
  auto tensors = op.expand_new();
  auto t1 = std::chrono::steady_clock::now();

  if (root)
  {
    op.writeBinary(filename, tensors);

    print("{} tensors up to maxShell = {}, written to\n  {}\n", tensors.size(),
          maxShell, filename);
    if (print_tensors)
      for (const auto& tensor : tensors) std::cout << tensor << std::endl;

    std::chrono::duration<double> t = t1 - t0;
    print("Time: {:.1f} s\n", t.count());
  }

  sam::finalize();
}
